// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Roulette} from "../src/Roulette.sol";

contract InvMutTest is Test {
    Roulette c;

    function setUp() public { c = new Roulette{value: 10 ether}(); }

    // fuzz over a block number offset to choose different block.number mod 15 values,
    // and over a caller address (the fuzzer provides an EOA address) which we will
    // make a funded caller using vm.prank and vm.deal. We also fuzz a timestamp delta
    // to ensure block.timestamp increases.
    function testFuzz_property(uint256 blockNumberOffset, address caller, uint256 tsDelta) public {
        // Keep domain wide but sensible
        // Ensure caller is non-zero and not the contract itself
        vm.assume(caller != address(0));
        vm.assume(caller != address(this));
        // bound tsDelta to a small range but allow zero to be excluded later
        tsDelta = bound(tsDelta, 1, 1 days);

        // Start from a known block number and timestamp
        uint256 baseBlock = 1; // small base
        uint256 chosenBlock = baseBlock + (blockNumberOffset % 1000); // vary mod 1000
        // warp to chosen timestamp strictly increasing from any previous value
        uint256 chosenTime = block.timestamp + tsDelta;

        // set the env to the chosen block/time
        vm.roll(chosenBlock);
        vm.warp(chosenTime);

        // Fund caller with enough balance to send 10 ether
        vm.deal(caller, 20 ether);

        // The test will send exactly 10 ether as required by the fallback
        // Call via low-level call to invoke fallback
        vm.prank(caller);
        (bool ok, ) = address(c).call{value: 10 ether}("");
        // The reference contract property (universal rule) is:
        //   If block.number % 15 == 0 then C transferred its entire balance to msg.sender,
        //   leaving address(c).balance == 0 after the call. Otherwise it did not transfer and
        //   address(c).balance remains > 0.
        // We assert the universal fact over the reference contract; the mutant (which uses == 1)
        // will differ for some block numbers and so the fuzzer can find such a case.

        uint256 mod15 = chosenBlock % 15;

        if (mod15 == 0) {
            // On the reference contract, the transfer happens and the contract balance becomes zero.
            // We assert that the call did not revert and balance is zero.
            assertTrue(ok && address(c).balance == 0);
        } else {
            // Otherwise reference does not transfer, so contract retains balance (should be 10 ether still)
            // The initial balance was 10 ether at deployment; after receiving 10 ether it should be 20
            // but because reference only transfers when mod15==0, here it should be non-zero (>= 10 ether)
            assertTrue(ok && address(c).balance != 0);
        }
    }
}
